-- Genuine schema-4 Sovereign vault fixture generated by eeed753 code. Synthetic data only.
PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE records (id TEXT PRIMARY KEY, content TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'manual',
          sensitivity TEXT NOT NULL CHECK(sensitivity IN ('private','sensitive')), status TEXT NOT NULL CHECK(status IN ('active','superseded')),
          created_at TEXT NOT NULL, supersedes_id TEXT, legacy INTEGER NOT NULL DEFAULT 0 CHECK(legacy IN (0, 1)));
CREATE TABLE tombstones (id TEXT PRIMARY KEY, deleted_at TEXT NOT NULL);
CREATE TABLE claims (
        id TEXT PRIMARY KEY CHECK(typeof(id) = 'text' AND length(id) BETWEEN 1 AND 200),
        text TEXT NOT NULL CHECK(typeof(text) = 'text' AND length(text) BETWEEN 1 AND 2000),
        origin TEXT NOT NULL CHECK(origin IN ('human', 'model', 'imported')),
        status TEXT NOT NULL CHECK(status IN ('proposed', 'approved', 'rejected', 'contested', 'superseded')),
        created_at TEXT NOT NULL CHECK(typeof(created_at) = 'text'),
        supersedes_id TEXT,
        CHECK(supersedes_id IS NULL OR (typeof(supersedes_id) = 'text' AND length(supersedes_id) BETWEEN 1 AND 200
                                        AND supersedes_id <> id))
    );
CREATE TABLE claim_sources (
        claim_id TEXT NOT NULL REFERENCES claims(id),
        record_id TEXT NOT NULL CHECK(typeof(record_id) = 'text' AND length(record_id) BETWEEN 1 AND 200),
        evidence_sha256 TEXT CHECK(evidence_sha256 IS NULL OR (typeof(evidence_sha256) = 'text' AND length(evidence_sha256) = 64)),
        PRIMARY KEY (claim_id, record_id)
    );
CREATE TABLE claim_events (
        seq INTEGER PRIMARY KEY AUTOINCREMENT CHECK(seq > 0),
        claim_id TEXT NOT NULL REFERENCES claims(id),
        from_status TEXT,
        to_status TEXT NOT NULL,
        actor TEXT NOT NULL CHECK(actor IN ('human', 'model', 'imported')),
        note TEXT CHECK(note IS NULL OR (typeof(note) = 'text' AND length(note) <= 500)),
        at TEXT NOT NULL CHECK(typeof(at) = 'text'),
        CHECK((from_status IS NULL) = (to_status = 'proposed')),
        CHECK(from_status IS NULL OR actor = 'human')
    );
CREATE TABLE claim_tombstones (
        id TEXT PRIMARY KEY CHECK(typeof(id) = 'text' AND length(id) BETWEEN 1 AND 200),
        deleted_at TEXT NOT NULL CHECK(typeof(deleted_at) = 'text')
    );
INSERT INTO "records" (rowid, id, content, source, sensitivity, status, created_at, supersedes_id, legacy) VALUES (1, CAST(X'6c65676163792f31' AS TEXT), CAST(X'4c65676163792073796e746865746963206e6f7465' AS TEXT), CAST(X'6d616e75616c' AS TEXT), CAST(X'70726976617465' AS TEXT), CAST(X'616374697665' AS TEXT), CAST(X'323032362d31302d30315430303a30303a30302b30303a3030' AS TEXT), NULL, 1);
INSERT INTO "records" (rowid, id, content, source, sensitivity, status, created_at, supersedes_id, legacy) VALUES (2, CAST(X'6e756c2d7265636f7264' AS TEXT), CAST(X'' AS TEXT), CAST(X'6d616e75616c' AS TEXT), CAST(X'70726976617465' AS TEXT), CAST(X'616374697665' AS TEXT), CAST(X'323032362d31302d30315430303a30303a30302b30303a3030' AS TEXT), NULL, 0);
INSERT INTO "records" (rowid, id, content, source, sensitivity, status, created_at, supersedes_id, legacy) VALUES (3, CAST(X'31663836613262392d383035662d343437642d623430612d613439633330633063663161' AS TEXT), CAST(X'4f7264696e6172792065766964656e636520666f722061204e554c2d6c656e67746820636c61696d' AS TEXT), CAST(X'6d616e75616c' AS TEXT), CAST(X'70726976617465' AS TEXT), CAST(X'616374697665' AS TEXT), CAST(X'323032362d31302d32325430333a35363a31372b30303a3030' AS TEXT), NULL, 0);
INSERT INTO "tombstones" (rowid, id, deleted_at) VALUES (1, CAST(X'6c65676163792d676f6e65' AS TEXT), CAST(X'323032362d31302d30315430303a30303a30302b30303a3030' AS TEXT));
INSERT INTO "claims" (rowid, id, text, origin, status, created_at, supersedes_id) VALUES (1, CAST(X'632d6e756c' AS TEXT), CAST(X'' AS TEXT), CAST(X'68756d616e' AS TEXT), CAST(X'70726f706f736564' AS TEXT), CAST(X'323032362d31302d30315430303a30303a30302b30303a3030' AS TEXT), NULL);
INSERT INTO "claim_sources" (rowid, claim_id, record_id, evidence_sha256) VALUES (1, CAST(X'632d6e756c' AS TEXT), CAST(X'31663836613262392d383035662d343437642d623430612d613439633330633063663161' AS TEXT), CAST(X'61313861613333633830613664616362303131383364623665643839643239383431646438316363613464303765653863323232393262666233333466313139' AS TEXT));
INSERT INTO "claim_events" (seq, claim_id, from_status, to_status, actor, note, at) VALUES (1, CAST(X'632d6e756c' AS TEXT), NULL, CAST(X'70726f706f736564' AS TEXT), CAST(X'68756d616e' AS TEXT), NULL, CAST(X'323032362d31302d30315430303a30303a30302b30303a3030' AS TEXT));
DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence (name, seq) VALUES (CAST(X'636c61696d5f6576656e7473' AS TEXT), 1);
CREATE INDEX ix_records_status ON records(status,created_at);
CREATE INDEX ix_claims_supersedes ON claims(supersedes_id);
CREATE INDEX ix_claim_events_claim ON claim_events(claim_id, seq);
CREATE INDEX ix_claim_sources_record ON claim_sources(record_id);
CREATE INDEX ix_records_supersedes ON records(supersedes_id);
CREATE TRIGGER claims_no_replace BEFORE INSERT ON claims WHEN EXISTS (SELECT 1 FROM claims WHERE id = NEW.id)
    BEGIN SELECT RAISE(ABORT, 'claim id already exists; claims are never replaced'); END;
CREATE TRIGGER claims_created_proposed BEFORE INSERT ON claims WHEN NEW.status <> 'proposed'
    BEGIN SELECT RAISE(ABORT, 'claims must be created as proposed'); END;
CREATE TRIGGER claims_not_resurrected BEFORE INSERT ON claims WHEN EXISTS (SELECT 1 FROM claim_tombstones WHERE id = NEW.id)
    BEGIN SELECT RAISE(ABORT, 'claim id was forgotten'); END;
CREATE TRIGGER claims_linear_supersession BEFORE INSERT ON claims WHEN
        EXISTS (SELECT 1 FROM claims WHERE supersedes_id = NEW.id)
        OR (NEW.supersedes_id IS NOT NULL AND (
            EXISTS (SELECT 1 FROM claims WHERE supersedes_id = NEW.supersedes_id)
            OR EXISTS (SELECT 1 FROM claims WHERE id = NEW.supersedes_id AND status <> 'superseded')))
    BEGIN SELECT RAISE(ABORT, 'invalid claim supersession'); END;
CREATE TRIGGER claims_immutable BEFORE UPDATE OF id, text, origin, created_at, supersedes_id ON claims
    BEGIN SELECT RAISE(ABORT, 'claims are immutable; supersede instead'); END;
CREATE TRIGGER claims_status_recorded BEFORE UPDATE OF status ON claims
    WHEN NEW.status IS NOT (SELECT to_status FROM claim_events WHERE claim_id = NEW.id ORDER BY seq DESC LIMIT 1)
      OR (OLD.status IN ('rejected', 'superseded') AND NEW.status IS NOT OLD.status)
    BEGIN SELECT RAISE(ABORT, 'claim status changes only through a recorded legal event'); END;
CREATE TRIGGER claims_removed_only_by_forgetting BEFORE DELETE ON claims WHEN NOT EXISTS (SELECT 1 FROM claim_tombstones WHERE id = OLD.id)
    BEGIN SELECT RAISE(ABORT, 'claims are removed only by forgetting (claim tombstone)'); END;
CREATE TRIGGER claim_sources_no_replace BEFORE INSERT ON claim_sources
    WHEN EXISTS (SELECT 1 FROM claim_sources WHERE claim_id = NEW.claim_id AND record_id = NEW.record_id)
    BEGIN SELECT RAISE(ABORT, 'claim evidence links are never replaced'); END;
CREATE TRIGGER claim_sources_fixed_insert BEFORE INSERT ON claim_sources
    WHEN NOT EXISTS (SELECT 1 FROM claims WHERE id = NEW.claim_id)
      OR EXISTS (SELECT 1 FROM claim_events WHERE claim_id = NEW.claim_id)
      OR (SELECT count(*) FROM claim_sources WHERE claim_id = NEW.claim_id) >= 8
      OR EXISTS (SELECT 1 FROM tombstones WHERE id = NEW.record_id)
    BEGIN SELECT RAISE(ABORT, 'claim evidence links are fixed at creation and cannot cite forgotten evidence'); END;
CREATE TRIGGER claim_sources_fixed_update BEFORE UPDATE ON claim_sources
    BEGIN SELECT RAISE(ABORT, 'claim evidence links are fixed at creation'); END;
CREATE TRIGGER claim_sources_fixed_delete BEFORE DELETE ON claim_sources WHEN NOT EXISTS (SELECT 1 FROM claim_tombstones WHERE id = OLD.claim_id)
    BEGIN SELECT RAISE(ABORT, 'claim evidence links are fixed at creation'); END;
CREATE TRIGGER claim_events_no_replace BEFORE INSERT ON claim_events WHEN EXISTS (SELECT 1 FROM claim_events WHERE seq = NEW.seq)
    BEGIN SELECT RAISE(ABORT, 'claim history is never replaced'); END;
CREATE TRIGGER claim_events_creation BEFORE INSERT ON claim_events WHEN NEW.from_status IS NULL AND (
        NOT EXISTS (SELECT 1 FROM claims WHERE id = NEW.claim_id AND status = 'proposed' AND origin = NEW.actor)
        OR EXISTS (SELECT 1 FROM claim_events WHERE claim_id = NEW.claim_id)
        OR NOT EXISTS (SELECT 1 FROM claim_sources WHERE claim_id = NEW.claim_id))
    BEGIN SELECT RAISE(ABORT, 'invalid claim creation event'); END;
CREATE TRIGGER claim_events_transition BEFORE INSERT ON claim_events WHEN NEW.from_status IS NOT NULL AND (
        NEW.actor <> 'human'
        OR (NEW.from_status || '>' || NEW.to_status) NOT IN ('approved>contested', 'approved>rejected', 'approved>superseded', 'contested>approved', 'contested>rejected', 'contested>superseded', 'proposed>approved', 'proposed>contested', 'proposed>rejected', 'proposed>superseded')
        OR NEW.from_status IS NOT (SELECT status FROM claims WHERE id = NEW.claim_id)
        OR NEW.from_status IS NOT (SELECT to_status FROM claim_events WHERE claim_id = NEW.claim_id ORDER BY seq DESC LIMIT 1))
    BEGIN SELECT RAISE(ABORT, 'illegal or stale claim transition'); END;
CREATE TRIGGER claim_events_apply AFTER INSERT ON claim_events WHEN NEW.from_status IS NOT NULL
    BEGIN UPDATE claims SET status = NEW.to_status WHERE id = NEW.claim_id; END;
CREATE TRIGGER claim_events_no_update BEFORE UPDATE ON claim_events BEGIN SELECT RAISE(ABORT, 'claim history is append-only'); END;
CREATE TRIGGER claim_events_no_delete BEFORE DELETE ON claim_events WHEN NOT EXISTS (SELECT 1 FROM claim_tombstones WHERE id = OLD.claim_id)
    BEGIN SELECT RAISE(ABORT, 'claim history is append-only'); END;
CREATE TRIGGER claim_tombstones_idempotent BEFORE INSERT ON claim_tombstones WHEN EXISTS (SELECT 1 FROM claim_tombstones WHERE id = NEW.id)
    BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER claim_tombstones_forget AFTER INSERT ON claim_tombstones BEGIN
        DELETE FROM claim_events WHERE claim_id = NEW.id;
        DELETE FROM claim_sources WHERE claim_id = NEW.id;
        DELETE FROM claims WHERE id = NEW.id;
    END;
CREATE TRIGGER claim_tombstones_no_update BEFORE UPDATE ON claim_tombstones BEGIN SELECT RAISE(ABORT, 'tombstones are permanent'); END;
CREATE TRIGGER claim_tombstones_no_delete BEFORE DELETE ON claim_tombstones BEGIN SELECT RAISE(ABORT, 'tombstones are permanent'); END;
CREATE TRIGGER records_well_formed BEFORE INSERT ON records WHEN
        typeof(NEW.id) <> 'text' OR typeof(NEW.content) <> 'text' OR length(NEW.content) > 10000
        OR typeof(NEW.source) <> 'text' OR typeof(NEW.created_at) <> 'text'
        OR (NEW.supersedes_id IS NOT NULL AND typeof(NEW.supersedes_id) <> 'text')
        OR (NEW.legacy = 0 AND (length(NEW.id) NOT BETWEEN 1 AND 200 OR length(NEW.content) < 1
                                OR length(NEW.source) NOT BETWEEN 1 AND 200
                                OR (NEW.supersedes_id IS NOT NULL AND length(NEW.supersedes_id) NOT BETWEEN 1 AND 200)))
    BEGIN SELECT RAISE(ABORT, 'malformed source record'); END;
CREATE TRIGGER records_no_replace BEFORE INSERT ON records WHEN EXISTS (SELECT 1 FROM records WHERE id = NEW.id)
    BEGIN SELECT RAISE(ABORT, 'record id already exists; evidence is never replaced'); END;
CREATE TRIGGER records_not_resurrected BEFORE INSERT ON records WHEN EXISTS (SELECT 1 FROM tombstones WHERE id = NEW.id)
    BEGIN SELECT RAISE(ABORT, 'record id was forgotten'); END;
CREATE TRIGGER records_not_after_claims BEFORE INSERT ON records
    WHEN EXISTS (SELECT 1 FROM claim_sources WHERE record_id = NEW.id)
    BEGIN SELECT RAISE(ABORT, 'evidence cannot appear after claims that cite it'); END;
CREATE TRIGGER records_not_after_correction BEFORE INSERT ON records
    WHEN EXISTS (SELECT 1 FROM records s WHERE s.supersedes_id = NEW.id AND (NEW.legacy = 0 OR s.legacy = 0))
    BEGIN SELECT RAISE(ABORT, 'a record cannot appear after its correction'); END;
CREATE TRIGGER records_linear_lineage BEFORE INSERT ON records WHEN NEW.supersedes_id IS NOT NULL AND (
        (NEW.legacy = 0 AND (NEW.supersedes_id = NEW.id
                             OR EXISTS (SELECT 1 FROM records s WHERE s.supersedes_id = NEW.supersedes_id)))
        OR (NEW.legacy = 1 AND (EXISTS (SELECT 1 FROM records s WHERE s.supersedes_id = NEW.supersedes_id AND s.legacy = 0)
                                OR EXISTS (SELECT 1 FROM records p WHERE p.id = NEW.supersedes_id AND p.legacy = 0))))
    BEGIN SELECT RAISE(ABORT, 'a record is corrected at most once and never by itself'); END;
CREATE TRIGGER records_correction_supersedes AFTER INSERT ON records WHEN NEW.legacy = 0 AND NEW.supersedes_id IS NOT NULL
    BEGIN UPDATE records SET status = 'superseded' WHERE id = NEW.supersedes_id AND status = 'active'; END;
CREATE TRIGGER records_immutable BEFORE UPDATE OF id, content, source, sensitivity, created_at, supersedes_id, legacy ON records
    BEGIN SELECT RAISE(ABORT, 'source records are immutable evidence'); END;
CREATE TRIGGER records_superseded_only_by_correction BEFORE UPDATE OF status ON records
    WHEN NOT (OLD.status = 'active' AND NEW.status = 'superseded'
              AND EXISTS (SELECT 1 FROM records WHERE supersedes_id = OLD.id))
    BEGIN SELECT RAISE(ABORT, 'evidence is superseded only by inserting its correction'); END;
CREATE TRIGGER records_removed_only_by_forgetting BEFORE DELETE ON records WHEN NOT EXISTS (SELECT 1 FROM tombstones WHERE id = OLD.id)
    BEGIN SELECT RAISE(ABORT, 'records are removed only by forgetting (tombstone)'); END;
CREATE TRIGGER tombstones_well_formed BEFORE INSERT ON tombstones
    WHEN typeof(NEW.id) <> 'text' OR typeof(NEW.deleted_at) <> 'text'
    BEGIN SELECT RAISE(ABORT, 'malformed tombstone'); END;
CREATE TRIGGER tombstones_idempotent BEFORE INSERT ON tombstones WHEN EXISTS (SELECT 1 FROM tombstones WHERE id = NEW.id)
    BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER tombstones_forget AFTER INSERT ON tombstones BEGIN
        INSERT INTO claim_tombstones(id, deleted_at)
            SELECT DISTINCT claim_id, NEW.deleted_at FROM claim_sources WHERE record_id = NEW.id;
        DELETE FROM records WHERE id = NEW.id;
    END;
CREATE TRIGGER tombstones_no_update BEFORE UPDATE ON tombstones BEGIN SELECT RAISE(ABORT, 'tombstones are permanent'); END;
CREATE TRIGGER tombstones_no_delete BEFORE DELETE ON tombstones BEGIN SELECT RAISE(ABORT, 'tombstones are permanent'); END;
PRAGMA user_version=4;
COMMIT;
